package com.nook.widgets;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.telephony.PhoneNumberUtils;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Widget-specific setup, separate from the shared design controls. */
public final class LibraryOptions {
    private LibraryOptions(){}
    private static void put(JSONObject json,String key,Object value){try{json.put(key,value);}catch(Exception e){throw new IllegalStateException(e);}}
    private static EditText input(Activity a,LinearLayout parent,String hint,String value){EditText field=new EditText(a);field.setHint(hint);field.setText(value);field.setTextColor(Ui.TEXT);field.setHintTextColor(Ui.MUTED);field.setSingleLine(true);field.setMinHeight(Ui.dp(a,48));parent.addView(field);return field;}
    private static void toggle(Activity a,LinearLayout p,String title,boolean value,java.util.function.Consumer<Boolean> change){Switch button=new Switch(a);button.setText(title);button.setTextColor(Ui.TEXT);button.setTextSize(14);button.setChecked(value);button.setMinHeight(Ui.dp(a,48));p.addView(button);button.setOnCheckedChangeListener((b,on)->change.accept(on));}
    private static void choice(Activity a,LinearLayout p,String[] values,int selected,java.util.function.IntConsumer change){Spinner spinner=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,values);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(selected);p.addView(spinner,new LinearLayout.LayoutParams(-1,Ui.dp(a,52)));spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> v){}public void onItemSelected(AdapterView<?> v,View child,int n,long id){if(child instanceof TextView t)t.setTextColor(Ui.TEXT);change.accept(n);}});}
    public static void add(Activity a,LinearLayout page,String kind,JSONObject settings,Runnable refresh,java.util.function.Consumer<Intent> choosePhoto){
        Ui.gap(page,14);
        if(kind.equals("photos")){
            page.addView(Ui.button(a,"Choose a photo",Ui.SURFACE,Ui.ACCENT,()->choosePhoto.accept(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION))));Ui.gap(page,10);
            EditText caption=input(a,page,"Optional photo caption",settings.optString("caption",""));caption.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});caption.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){put(settings,"caption",s.toString());refresh.run();}});
        }else if(kind.equals("weather")){
            page.addView(Ui.button(a,"Choose weather city",Ui.SURFACE,Ui.ACCENT,()->city(a,settings,refresh)));Ui.gap(page,10);page.addView(Ui.text(a,"City search and forecasts use Open-Meteo. Only the selected city coordinates are sent for forecasts; your phone's location is not requested.",12,Ui.MUTED));toggle(a,page,"Use Fahrenheit",settings.optBoolean("fahrenheit",false),on->{put(settings,"fahrenheit",on);refresh.run();});
            page.addView(Ui.button(a,"Open-Meteo · Weather data & attribution",Ui.SURFACE,Ui.ACCENT,()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://open-meteo.com/")))));
        }else if(kind.equals("calendar")||kind.equals("agenda")){
            page.addView(Ui.button(a,"Calendar access",Ui.SURFACE,Ui.ACCENT,()->a.startActivity(WidgetUtilityActivity.intent(a,"calendar_access",-1,""))));page.addView(Ui.text(a,"Read-only access shows the events in your phone's visible calendars. The date grid works without permission.",12,Ui.MUTED));if(kind.equals("calendar"))toggle(a,page,"Start weeks on Sunday",settings.optBoolean("sunday",false),on->{put(settings,"sunday",on);refresh.run();});
        }else if(kind.equals("music")){
            MusicOptions.add(a,page,settings,refresh);
        }else if(kind.equals("worldclock")){
            page.addView(Ui.button(a,"Choose your three time zones",Ui.SURFACE,Ui.ACCENT,()->zones(a,settings,refresh)));toggle(a,page,"Use 24-hour clocks",settings.optBoolean("clock24",true),on->{put(settings,"clock24",on);refresh.run();});
        }else if(kind.equals("countdown")){
            EditText occasion=input(a,page,"Occasion, e.g. Holiday",settings.optString("occasion",""));occasion.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});occasion.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){put(settings,"occasion",s.toString());refresh.run();}});
            page.addView(Ui.button(a,"Choose event date",Ui.SURFACE,Ui.ACCENT,()->{LocalDate saved=WidgetData.targetDay(settings);LocalDate date=saved==null?LocalDate.now().plusDays(1):saved;new DatePickerDialog(a,(picker,y,m,d)->{put(settings,"targetDay",LocalDate.of(y,m+1,d).toString());put(settings,"targetDate",LocalDate.of(y,m+1,d).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli());refresh.run();},date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show();}));
        }else if(kind.equals("contacts"))page.addView(Ui.button(a,"Edit your favorite people",Ui.SURFACE,Ui.ACCENT,()->contacts(a,settings,refresh)));
        else if(kind.equals("controls"))page.addView(Ui.button(a,"Choose three shortcuts",Ui.SURFACE,Ui.ACCENT,()->{LinearLayout controls=Ui.column(a);Ui.pad(controls,24,12);for(int n=0;n<3;n++){final int slot=n;controls.addView(Ui.text(a,"Shortcut "+(n+1),12,Ui.MUTED));choice(a,controls,LibraryWidgets.TOOL_NAMES,WidgetDesign.clamp(settings.optInt("control"+n,settings.optInt("variant",0)==0?n:new int[]{6,7,5}[n]),0,7),v->{put(settings,"control"+slot,v);refresh.run();});}new AlertDialog.Builder(a).setTitle("Your quick controls").setView(controls).setPositiveButton("Done",null).show();}));
        else if(kind.equals("battery"))page.addView(Ui.text(a,"Shows this phone's real battery data. Tap the widget to refresh; Android also refreshes it periodically and when power is connected.",12,Ui.MUTED));
        else if(kind.equals("search"))page.addView(Ui.text(a,"Opens a search entry screen and your selected web provider in the browser. Voice input uses an installed speech provider.",12,Ui.MUTED));
    }
    private static void zones(Activity a,JSONObject settings,Runnable refresh){
        LinearLayout content=Ui.column(a);Ui.pad(content,24,12);content.addView(Ui.text(a,"Search by city. Clocks follow that city's daylight-saving changes.",13,Ui.MUTED));String[] defaults={TimeZone.getDefault().getID(),"UTC","America/New_York"};
        for(int n=0;n<3;n++){final int slot=n;TextView button=Ui.button(a,"City "+(n+1)+" · "+cityName(settings.optString("zone"+n,defaults[n])),Ui.SURFACE,Ui.TEXT,()->{});Ui.click(button,()->zonePicker(a,zone->{put(settings,"zone"+slot,zone);button.setText("City "+(slot+1)+" · "+cityName(zone));refresh.run();}));content.addView(button);Ui.gap(content,8);}new AlertDialog.Builder(a).setTitle("World clock cities").setView(content).setPositiveButton("Done",null).show();
    }
    public static String cityName(String zone){return switch(zone){case "Asia/Calcutta"->"Kolkata";case "US/Eastern"->"New York";case "US/Pacific"->"Los Angeles";default->zone.substring(zone.lastIndexOf('/')+1).replace('_',' ');};}
    private static void zonePicker(Activity a,java.util.function.Consumer<String> selected){
        LinearLayout content=Ui.column(a);Ui.pad(content,18,8);EditText search=input(a,content,"Search a city or time zone","");List<String> zones=new ArrayList<>(ZoneId.getAvailableZoneIds());zones.sort(Comparator.comparing(LibraryOptions::cityName,String.CASE_INSENSITIVE_ORDER));List<String> filtered=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_list_item_1);ListView list=new ListView(a);list.setAdapter(adapter);content.addView(list,new LinearLayout.LayoutParams(-1,Ui.dp(a,300)));
        Runnable filter=()->{String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);filtered.clear();adapter.clear();for(String zone:zones)if((cityName(zone)+" "+zone).toLowerCase(Locale.ROOT).contains(query)){filtered.add(zone);String offset=ZoneId.of(zone).getRules().getOffset(Instant.now()).getId();adapter.add(cityName(zone)+" · "+(offset.equals("Z")?"GMT":"GMT"+offset));}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(android.text.Editable e){filter.run();}public void onTextChanged(CharSequence s,int st,int before,int count){}});filter.run();AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Choose a city").setView(content).setNegativeButton("Cancel",null).create();list.setOnItemClickListener((p,v,n,id)->{selected.accept(filtered.get(n));dialog.dismiss();});dialog.show();
    }
    private static void contacts(Activity a,JSONObject settings,Runnable refresh){
        LinearLayout content=Ui.column(a);Ui.pad(content,24,12);EditText[] names=new EditText[3],phones=new EditText[3];for(int n=0;n<3;n++){names[n]=input(a,content,"Favorite "+(n+1)+" name",settings.optString("name"+n,""));names[n].setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(18)});phones[n]=input(a,content,"Favorite "+(n+1)+" phone",settings.optString("phone"+n,""));phones[n].setInputType(android.text.InputType.TYPE_CLASS_PHONE);}ScrollView scroll=new ScrollView(a);scroll.addView(content);
        AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Your favorite people").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String[] normalized=new String[3];for(int n=0;n<3;n++){normalized[n]=PhoneNumberUtils.normalizeNumber(phones[n].getText().toString());if(!normalized[n].isEmpty()&&!normalized[n].matches("\\+?[0-9]{3,18}")||normalized[n].isEmpty()&&!names[n].getText().toString().trim().isEmpty()){phones[n].setError("Enter a phone number, or clear both fields");return;}}for(int n=0;n<3;n++){put(settings,"name"+n,names[n].getText().toString().trim());put(settings,"phone"+n,normalized[n]);}refresh.run();dialog.dismiss();}));dialog.show();
    }
    private static void city(Activity a,JSONObject settings,Runnable refresh){
        LinearLayout content=Ui.column(a);Ui.pad(content,24,12);EditText search=input(a,content,"City or postal code",settings.optString("city",""));TextView status=Ui.text(a,"City search uses Open-Meteo / GeoNames.",12,Ui.MUTED);content.addView(status);
        AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Weather city").setView(content).setNegativeButton("Cancel",null).setPositiveButton("Find city",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String query=search.getText().toString().trim();if(query.length()<2){search.setError("Enter at least two characters");return;}dialog.getButton(-1).setEnabled(false);status.setText("Searching…");new Thread(()->{try{JSONArray cities=WeatherData.cities(query);a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed()||!dialog.isShowing())return;dialog.getButton(-1).setEnabled(true);if(cities.length()==0){status.setText("No cities found. Try a nearby city or postal code.");return;}String[] labels=new String[cities.length()];for(int n=0;n<labels.length;n++){JSONObject city=cities.optJSONObject(n);labels[n]=city.optString("name")+" · "+city.optString("admin1","")+" · "+city.optString("country","");}new AlertDialog.Builder(a).setTitle("Choose a city").setItems(labels,(pick,n)->{JSONObject city=cities.optJSONObject(n);put(settings,"city",city.optString("name"));put(settings,"latitude",city.optDouble("latitude"));put(settings,"longitude",city.optDouble("longitude"));dialog.dismiss();refresh.run();JSONObject copy;try{copy=new JSONObject(settings.toString());}catch(Exception e){return;}new Thread(()->{WeatherData.refresh(a.getApplicationContext(),copy,true);Widgets.updateAll(a.getApplicationContext());a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())refresh.run();});},"Nook forecast").start();}).show();});}catch(Exception e){a.runOnUiThread(()->{if(dialog.isShowing()){dialog.getButton(-1).setEnabled(true);status.setText("City search couldn't connect. Check your internet connection and try again.");}});}},"Nook city search").start();}));dialog.show();
    }
}
